=== FILE: skid_buffer.v ===
`timescale 1ns/1ps
`default_nettype none

// skid_buffer: a register slice for one valid/ready stream.
// Implements interface_spec.md and microarchitecture.md (two registers:
// output register m_valid/m_data and skid register skid_valid/skid_data).
// Every output is a flop (s_ready is the inverse of a flop); the inputs
// reach only next-state logic.
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat is accepted on this edge.
    wire s_fire = s_valid && s_ready;

    // Upstream ready: high while at most one beat is held.
    assign s_ready = !skid_valid;

    // Next state (microarchitecture section 3).
    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat moves to the output register.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Load the input (a beat only if s_valid).
                m_valid_d    = s_valid;
                m_data_d     = s_data;
            end
        end else if (s_fire) begin
            // Output stalled: the accepted beat goes to the skid register.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    // Design-intent assertions (not part of synthesis or simulation).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // The skid register is only full while the output register is full.
    always @(*) begin
        if (f_past_valid && skid_valid) assert(m_valid);
    end

    // A beat offered and not taken stays offered with the same data.
    always @(posedge clk) begin
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
            assert(m_valid);
            assert(m_data == $past(m_data));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
