`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for skid_buffer.
// Two lanes, WIDTH 8 and WIDTH 1, each with its own DUT, a queue model of
// up to two beats, directed tests and random traffic.
//
// Check IDs:
//   1  m_valid == (model holds >= 1 beat)      2  s_ready == (model holds <= 1)
//   3  m_data == oldest model beat             4  hold: m_valid stays high
//   5  hold: m_data unchanged                  6  s_ready does not move inside a cycle
//   7  m_valid does not move inside a cycle    8  m_data does not move inside a cycle
//   20-23 drain ends empty, m_valid low, s_ready high, every beat out once
//   30-31 reset values                         32-34 one-cycle latency
//   35-38 full throughput                      40-45 stall with one and two beats held
//   46-47 ready low for one and several cycles 50-54 reset with beats held
//   60  random traffic reached a full slice    99  timeout (top level)

module skid_buffer_lane #(
    parameter integer WIDTH = 8,
    parameter [31:0]  SEED  = 32'h1234_5678
) (
    input  wire        clk,
    output reg  [31:0] passed,
    output reg  [31:0] failed,
    output reg         done
);

    reg              rst_n;
    reg              s_valid;
    reg  [WIDTH-1:0] s_data;
    reg              m_ready;
    wire             s_ready;
    wire             m_valid;
    wire [WIDTH-1:0] m_data;

    skid_buffer #(.WIDTH(WIDTH)) dut (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    // Model state.
    integer          cnt;
    reg  [WIDTH-1:0] q0;
    reg  [WIDTH-1:0] q1;
    reg              known;
    integer          n_in;
    integer          n_out;
    integer          n_drop;
    integer          n_full;
    reg              hold_pending;
    reg  [WIDTH-1:0] hold_data;

    // Stimulus state.
    reg  [31:0]      rng;
    reg  [31:0]      seq;
    integer          i;
    integer          k;
    integer          base_in;
    integer          base_out;
    integer          base_full;
    reg              sv_t;
    reg              mr_t;
    reg  [4:0]       sv_p;
    reg  [4:0]       mr_p;

    task check;
        input         cond;
        input integer id;
        begin
            if (cond === 1'b1) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("skid_buffer_tb WIDTH=%0d: check %0d failed at %0t", WIDTH, id, $time);
            end
        end
    endtask

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // One clock cycle. Called just after a falling edge with the inputs set.
    task cycle;
        reg             sv;
        reg             mr;
        reg             sf;
        reg             mf;
        reg             o_sr;
        reg             o_mv;
        reg             hp;
        reg [WIDTH-1:0] sd;
        reg [WIDTH-1:0] o_md;
        begin
            if (known) begin
                check(m_valid === (cnt != 0), 1);
                check(s_ready === (cnt < 2), 2);
                if (cnt != 0) check(m_data === q0, 3);
                if (hold_pending) begin
                    check(m_valid === 1'b1, 4);
                    check(m_data === hold_data, 5);
                end
            end
            // No combinational path from inputs to outputs.
            o_sr = s_ready;
            o_mv = m_valid;
            o_md = m_data;
            sv = s_valid;
            mr = m_ready;
            sd = s_data;
            s_valid = ~sv;
            m_ready = ~mr;
            s_data  = ~sd;
            #1;
            if (known) begin
                check(s_ready === o_sr, 6);
                check(m_valid === o_mv, 7);
                if (o_mv) check(m_data === o_md, 8);
            end
            s_valid = sv;
            m_ready = mr;
            s_data  = sd;
            #1;
            sf = sv && (cnt < 2);
            mf = mr && (cnt != 0);
            hp = known && rst_n && (cnt != 0) && !mr;
            hold_data = q0;
            @(posedge clk);
            if (!rst_n) begin
                if (known) n_drop = n_drop + cnt;
                cnt   = 0;
                known = 1'b1;
                hp    = 1'b0;
            end else if (known) begin
                if (mf) begin
                    q0    = q1;
                    cnt   = cnt - 1;
                    n_out = n_out + 1;
                end
                if (sf) begin
                    if (cnt == 0) q0 = sd;
                    else          q1 = sd;
                    cnt  = cnt + 1;
                    n_in = n_in + 1;
                end
            end
            if (cnt == 2) n_full = n_full + 1;
            hold_pending = hp;
            @(negedge clk);
        end
    endtask

    task drive;
        input             sv;
        input [WIDTH-1:0] sd;
        input             mr;
        begin
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            cycle;
        end
    endtask

    task drain;
        integer j;
        begin
            j = 0;
            while ((cnt != 0) && (j < 8)) begin
                drive(1'b0, seq[WIDTH-1:0], 1'b1);
                j = j + 1;
            end
            check(cnt == 0, 20);
            check(m_valid === 1'b0, 21);
            check(s_ready === 1'b1, 22);
            check(n_in == (n_out + n_drop), 23);
        end
    endtask

    initial begin
        passed       = 32'd0;
        failed       = 32'd0;
        done         = 1'b0;
        rst_n        = 1'b0;
        s_valid      = 1'b0;
        m_ready      = 1'b0;
        s_data       = {WIDTH{1'b0}};
        cnt          = 0;
        q0           = {WIDTH{1'b0}};
        q1           = {WIDTH{1'b0}};
        known        = 1'b0;
        n_in         = 0;
        n_out        = 0;
        n_drop       = 0;
        n_full       = 0;
        hold_pending = 1'b0;
        hold_data    = {WIDTH{1'b0}};
        rng          = SEED;
        seq          = 32'd0;
        sv_t         = 1'b0;
        mr_t         = 1'b0;
        sv_p         = 5'd8;
        mr_p         = 5'd8;
        @(negedge clk);

        // Reset values (an offered beat during reset is not taken).
        rst_n = 1'b0;
        drive(1'b1, {WIDTH{1'b1}}, 1'b0);
        drive(1'b0, {WIDTH{1'b0}}, 1'b1);
        rst_n = 1'b1;
        check(m_valid === 1'b0, 30);
        check(s_ready === 1'b1, 31);

        // One-cycle latency.
        seq = 32'h0000_00A5;
        drive(1'b1, seq[WIDTH-1:0], 1'b1);
        check(m_valid === 1'b1, 32);
        check(m_data === seq[WIDTH-1:0], 33);
        drive(1'b0, ~seq[WIDTH-1:0], 1'b1);
        check(m_valid === 1'b0, 34);

        // Full throughput: one beat in and one out on every edge.
        base_in  = n_in;
        base_out = n_out;
        for (i = 0; i < 64; i = i + 1) begin
            seq = seq + 32'd1;
            drive(1'b1, seq[WIDTH-1:0], 1'b1);
            check(m_valid === 1'b1, 35);
            check(s_ready === 1'b1, 36);
        end
        check((n_in - base_in) == 64, 37);
        check((n_out - base_out) == 63, 38);
        drain;

        // Stall with one beat held: a second beat must be accepted.
        seq = seq + 32'd1;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        check(m_valid === 1'b1, 40);
        check(s_ready === 1'b1, 41);
        seq = seq + 32'd1;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        check(cnt == 2, 42);
        check(s_ready === 1'b0, 43);
        // Two beats held: a third must not be accepted.
        base_in = n_in;
        for (i = 0; i < 5; i = i + 1) begin
            seq = seq + 32'd1;
            drive(1'b1, seq[WIDTH-1:0], 1'b0);
            check(s_ready === 1'b0, 44);
        end
        check(n_in == base_in, 45);
        // Ready rises after the stall while the sender keeps offering.
        for (i = 0; i < 6; i = i + 1) begin
            seq = seq + 32'd1;
            drive(1'b1, seq[WIDTH-1:0], 1'b1);
        end
        drain;

        // Ready low for one cycle and for several, sender always offering.
        base_out = n_out;
        for (i = 0; i < 40; i = i + 1) begin
            k = i % 10;
            mr_t = (k != 2) && ((k < 5) || (k > 8));
            seq = seq + 32'd1;
            drive(1'b1, seq[WIDTH-1:0], mr_t);
        end
        check(n_out > base_out, 46);
        drain;
        check(n_in == (n_out + n_drop), 47);

        // Reset with two beats held.
        seq = seq + 32'd1;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        seq = seq + 32'd1;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        check(cnt == 2, 50);
        rst_n = 1'b0;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        rst_n = 1'b1;
        check(m_valid === 1'b0, 51);
        check(s_ready === 1'b1, 52);
        // Reset with one beat held and the receiver ready.
        seq = seq + 32'd1;
        drive(1'b1, seq[WIDTH-1:0], 1'b0);
        rst_n = 1'b0;
        drive(1'b1, seq[WIDTH-1:0], 1'b1);
        rst_n = 1'b1;
        check(m_valid === 1'b0, 53);
        check(s_ready === 1'b1, 54);

        // Random traffic against the model, with occasional reset.
        base_full = n_full;
        for (k = 0; k < 4; k = k + 1) begin
            if (k == 0) begin
                sv_p = 5'd12;
                mr_p = 5'd12;
            end else if (k == 1) begin
                sv_p = 5'd12;
                mr_p = 5'd4;
            end else if (k == 2) begin
                sv_p = 5'd4;
                mr_p = 5'd12;
            end else begin
                sv_p = 5'd8;
                mr_p = 5'd8;
            end
            for (i = 0; i < 600; i = i + 1) begin
                next_rand;
                rst_n = (rng[15:8] != 8'h00);
                if ({1'b0, rng[3:0]} < sv_p) begin
                    seq  = seq + 32'd1;
                    sv_t = 1'b1;
                end else begin
                    sv_t = 1'b0;
                end
                mr_t = ({1'b0, rng[7:4]} < mr_p);
                drive(sv_t, seq[WIDTH-1:0], mr_t);
            end
        end
        rst_n = 1'b1;
        check(n_full > base_full, 60);
        drain;

        done = 1'b1;
    end

endmodule

module skid_buffer_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire [31:0] p8;
    wire [31:0] f8;
    wire        d8;
    wire [31:0] p1;
    wire [31:0] f1;
    wire        d1;

    skid_buffer_lane #(.WIDTH(8), .SEED(32'h1357_9BDF)) lane_w8 (
        .clk    (clk),
        .passed (p8),
        .failed (f8),
        .done   (d8)
    );

    skid_buffer_lane #(.WIDTH(1), .SEED(32'h2468_ACE1)) lane_w1 (
        .clk    (clk),
        .passed (p1),
        .failed (f1),
        .done   (d1)
    );

    reg [8*64-1:0] nonce;
    reg [31:0]     cycles;
    reg [31:0]     total_passed;
    reg [31:0]     total_failed;

    initial begin
        nonce  = {512{1'b0}};
        cycles = 32'd0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {512{1'b0}};
        @(posedge clk);
        while (!((d8 === 1'b1) && (d1 === 1'b1)) && (cycles < 32'd20000)) begin
            @(posedge clk);
            cycles = cycles + 32'd1;
        end
        @(negedge clk);
        total_passed = p8 + p1;
        total_failed = f8 + f1;
        if (!((d8 === 1'b1) && (d1 === 1'b1))) begin
            total_failed = total_failed + 32'd1;
            $error("skid_buffer_tb: check 99 failed, timeout after %0d cycles", cycles);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_passed, total_failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
